mod model;mod logic;
fn main(){let a:Vec<String>=std::env::args().collect();let limit:i64=a[1].parse().unwrap();let data:Vec<u8>=(0..a[2].len()).step_by(2).map(|i|u8::from_str_radix(&a[2][i..i+2],16).unwrap()).collect();
if a.len()>3 {let repeats:i64=a[4].parse().unwrap();let mut total=0i64;for i in 0..repeats {let v=logic::run(std::hint::black_box(&data),limit+i%3);total+=std::hint::black_box(v.consumed+v.error+v.frames.iter().map(|b|b.len() as i64+b.iter().map(|x|*x as i64).sum::<i64>()).sum::<i64>());}println!("{}",total);} else {let v=logic::run(&data,limit);let strings:Vec<String>=v.frames.iter().map(|b|format!("\"{}\"",b.iter().map(|x|format!("{:02x}",x)).collect::<String>())).collect();println!("{{\"frames\":[{}],\"consumed\":{},\"error\":{}}}",strings.join(","),v.consumed,v.error);}}
